const Atlas = lazy(() => import('@/features/atlas'));
const Diagnostics = lazy(() => import('@/features/diagnostics'));
const DnsTools = lazy(() => import('@/features/dns-tools'));
const BrowserDns = lazy(() => import('@/features/browser-dns'));
type Page = 'overview' | 'ports' | 'connections' | 'processes' | 'exposure' | 'analytics' | 'health' | 'snapshots' | 'activity' | 'atlas' | 'diagnostics' | 'dns' | 'settings';
type PortFilter = 'all' | 'web' | 'dev' | 'system' | 'favorites';
type Theme = 'light' | 'dark' | 'system';
type Sort = 'port' | 'service' | 'process' | 'latency' | 'exposure' | 'seen';
const routes: { id: Page; en: string; idLabel: string; icon: LucideIcon; key?: string }[] = [
  { id: 'overview', en: 'Overview', idLabel: 'Ringkasan', icon: LayoutDashboard },
  { id: 'ports', en: 'Ports', idLabel: 'Port', icon: Radio, key: 'page.title' },
  { id: 'connections', en: 'Connections', idLabel: 'Koneksi', icon: Network },
  { id: 'processes', en: 'Processes', idLabel: 'Proses', icon: Cpu, key: 'kpi.processes' },
  { id: 'exposure', en: 'Exposure', idLabel: 'Eksposur', icon: Shield },
  { id: 'analytics', en: 'Analytics', idLabel: 'Analitik', icon: Activity },
  { id: 'health', en: 'Health checks', idLabel: 'Pemeriksaan', icon: HeartPulse },
  { id: 'snapshots', en: 'Snapshots', idLabel: 'Snapshot', icon: Copy },
  { id: 'activity', en: 'Activity log', idLabel: 'Log aktivitas', icon: History, key: 'activity.title' },
  { id: 'atlas', en: 'Network atlas', idLabel: 'Atlas jaringan', icon: MapIcon },
  { id: 'diagnostics', en: 'Ping / Traceroute', idLabel: 'Ping / Traceroute', icon: SquareTerminal },
  { id: 'dns', en: 'DNS tools', idLabel: 'Alat DNS', icon: Globe },
  { id: 'settings', en: 'Settings', idLabel: 'Pengaturan', icon: Settings2 },
];
const routeTitle = (route: typeof routes[number]) => route.key ? t(route.key) : l(route.en, route.idLabel);
const pageFromHash = (): Page => { const hash = window.location.hash.replace(/^#\/?/, '').split('?')[0]; return routes.some(route => route.id === hash) ? hash as Page : 'overview'; };
const validPort = (value: unknown): value is number => typeof value === 'number' && Number.isInteger(value) && value > 0 && value <= 65535;
const portList = (values: number[]) => [...new Set(values.filter(validPort))];
const serviceName = (port: Port) => port.title || port.framework || port.processName || t(port.protocol === 'tcp' ? 'service.tcpGeneric' : 'service.httpGeneric');

async function copy(value: string) {
  try { await copyText(value); toast.success(t('toast.copied')); }
  catch { toast.error(l('Clipboard unavailable. Please copy the address manually.', 'Clipboard tidak tersedia. Salin alamat secara manual.')); }
}
function exportPorts(ports: Port[], format: 'json' | 'csv') {
  if (!ports.length) { toast.error(l('No ports to export.', 'Tidak ada port untuk diekspor.')); return; }
  const name = 'portscope-ports-' + new Date().toISOString().replace(/[:.]/g, '-');
  try {
    if (format === 'json') download(name + '.json', JSON.stringify({ exportedAt: new Date().toISOString(), ports: ports.map(({ port, protocol, processName, pid, bindAddresses, wildcard, statusCode, responseTimeMs, latencyHistory, category, firstSeenAt, onlineForMs }) => ({ port, protocol, processName, pid, bindAddresses, wildcard, statusCode, responseTimeMs, latencyHistory, category, firstSeenAt, onlineForMs })) }, null, 2));
    else download(name + '.csv', toCsv([['Port', 'Protocol', 'Service', 'Process', 'PID', 'Bind addresses', 'Wildcard bind', 'HTTP status', 'Latency ms', 'First observed'], ...ports.map(port => [port.port, port.protocol, serviceName(port), port.processName, port.pid, port.bindAddresses.join('; '), port.wildcard, port.statusCode, port.responseTimeMs, port.firstSeenAt])]), 'text/csv;charset=utf-8');
    toast.success(l('Export downloaded', 'Ekspor diunduh'));
  } catch (error) { toast.error(error instanceof Error ? error.message : l('Export failed.', 'Ekspor gagal.')); }
}
function IconButton({ label, children, ...props }: React.ComponentProps<typeof Button> & { label: string }) {
  return <Tooltip><TooltipTrigger asChild><Button variant="ghost" size="icon" aria-label={label} {...props}>{children}</Button></TooltipTrigger><TooltipContent>{label}</TooltipContent></Tooltip>;
}
function LoadingWorkspace() {
  return <div aria-busy="true" aria-label={t('common.loading')} className="space-y-6"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[0, 1, 2, 3].map(key => <Card key={key} className="gap-4"><CardContent className="space-y-4"><Skeleton className="h-3 w-24" /><Skeleton className="h-9 w-20" /><Skeleton className="h-3 w-32" /></CardContent></Card>)}</div><Skeleton className="h-72 w-full rounded-xl" /><Skeleton className="h-80 w-full rounded-xl" /></div>;
}

function Workbench() {
  const { state, network, history, connection, error, live, setLive, refresh } = usePortScope();
  const { setOpenMobile, isMobile } = useSidebar();
  const [page, setPage] = useState<Page>(pageFromHash);
  const [diagnosticFocus, setDiagnosticFocus] = useState(false);
  const monitoringFocus = page === 'diagnostics' && diagnosticFocus;
  const [routeQuery, setRouteQuery] = useState(() => window.location.hash.split('?')[1] || '');
  const diagnosticParams = new URLSearchParams(routeQuery);
  const diagnosticTarget = diagnosticParams.get('target') || '';
  const diagnosticKind = (['ping', 'mtr', 'tcp', 'tls'].includes(diagnosticParams.get('kind') || '') ? diagnosticParams.get('kind') : 'ping') as DiagnosticKind;
  const [locale, setLanguage] = useState(getLocale);
  const [theme, setTheme] = useStorage<Theme>('portscope.theme', 'system');
  const [systemDark, setSystemDark] = useState(() => window.matchMedia('(prefers-color-scheme: dark)').matches);
  const [savedFavorites, setFavorites] = useStorage<number[]>('portscope.favorites', []);
  const [savedWatchlist, setWatchlist] = useStorage<number[]>('portscope.watchlist', []);
  const [view, setView] = useStorage<'table' | 'grid'>('portscope.view', 'table');
  const [compact, setCompact] = useStorage('portscope.compact', false);
  const [pageSize, setPageSize] = useStorage('portscope.pageSize', 15);
  const favorites = useMemo(() => portList(savedFavorites), [savedFavorites]);
  const watchlist = useMemo(() => portList(savedWatchlist).slice(0, 20), [savedWatchlist]);
  const [query, setQuery] = useState('');
  const [filter, setFilter] = useState<PortFilter>('all');
  const [watchInput, setWatchInput] = useState('');
  const [watchError, setWatchError] = useState<{ key: string; params?: Record<string, unknown> } | null>(null);
  const [commandOpen, setCommandOpen] = useState(false);
  const [helpOpen, setHelpOpen] = useState(false);
  const [detail, setDetail] = useState<Port | null>(null);
  const [detailOpen, setDetailOpen] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [now, setNow] = useState(Date.now);
  const searchRef = useRef<HTMLInputElement>(null);
  const headingRef = useRef<HTMLHeadingElement>(null);
  const opener = useRef<HTMLElement | null>(null);
  const previousWatched = useRef(new Map<number, boolean>());
  const resolvedTheme = theme === 'light' ? 'light' : theme === 'system' ? systemDark ? 'dark' : 'light' : 'dark';
  const route = routes.find(item => item.id === page)!;
  const scanAge = state?.meta.scannedAt ? Math.max(0, now - Date.parse(state.meta.scannedAt)) : null;
  const legacyServer = !!state && (Number.parseInt(state.meta.version, 10) < 2 || (Number.parseInt(state.meta.version, 10) === 2 && Number(state.meta.version.split('.')[1]) < 2));
  const stale = live && scanAge != null && scanAge > Math.max(15000, (state?.meta.scanIntervalMs ?? 3000) * 4);
  const scan = useCallback(async () => { setRefreshing(true); try { await refresh(); } catch (error) { toast.error(error instanceof Error ? error.message : t('error.scanFailed')); } finally { setRefreshing(false); } }, [refresh]);
  const navigate = useCallback((next: Page) => { setPage(next); setRouteQuery(''); window.location.hash = next; setOpenMobile(false); }, [setOpenMobile]);
  const openSettings = useCallback(() => navigate('settings'), [navigate]);
  const diagnose = (target: string, kind = 'ping') => { const query = new URLSearchParams({ target, kind }).toString(); setPage('diagnostics'); setRouteQuery(query); window.location.hash = 'diagnostics?' + query; setOpenMobile(false); };
  const changeLanguage = (next: string) => { if (LANGUAGES.some(language => language.code === next)) setLanguage(setLocale(next)); };
  const toggleFavorite = (port: number) => { if (validPort(port)) setFavorites(previous => { const values = portList(previous); return values.includes(port) ? values.filter(value => value !== port) : [...values, port]; }); };
  const toggleWatch = (port: number) => {
    if (!validPort(port)) return;
    if (watchlist.includes(port)) { setWatchlist(watchlist.filter(value => value !== port)); return; }
    if (watchlist.length >= 20) { toast.error(t('watchlist.errMax', { count: 20 })); return; }
    setWatchlist([...watchlist, port]); toast.success(t('watchlist.addedTitle', { port }));
  };
  const addWatch = (event: React.FormEvent) => {
    event.preventDefault();
    const port = Number(watchInput);
    if (!/^\d+$/.test(watchInput.trim()) || !validPort(port)) { setWatchError({ key: 'watchlist.errPort' }); return; }
    if (watchlist.includes(port)) { setWatchError({ key: 'watchlist.errDuplicate', params: { port } }); return; }
    if (watchlist.length >= 20) { setWatchError({ key: 'watchlist.errMax', params: { count: 20 } }); return; }
    setWatchError(null); setWatchInput(''); toggleWatch(port);
  };
  const openPort = (port: Port) => { opener.current = document.activeElement instanceof HTMLElement ? document.activeElement : null; setDetail(port); setDetailOpen(true); };
  const focusSearch = useCallback(() => { if (page !== 'ports' && page !== 'overview') navigate('ports'); requestAnimationFrame(() => searchRef.current?.focus()); }, [page, navigate]);

  useEffect(() => { const update = () => { setPage(pageFromHash()); setRouteQuery(window.location.hash.split('?')[1] || ''); }; window.addEventListener('hashchange', update); return () => window.removeEventListener('hashchange', update); }, []);
  useEffect(() => { const media = window.matchMedia('(prefers-color-scheme: dark)'); const update = () => setSystemDark(media.matches); media.addEventListener('change', update); return () => media.removeEventListener('change', update); }, []);
  useEffect(() => { document.documentElement.classList.toggle('dark', resolvedTheme === 'dark'); document.documentElement.style.colorScheme = resolvedTheme; }, [resolvedTheme]);
  useEffect(() => { document.title = state ? t('app.title', { count: state.stats.totalPorts }) : t('app.titlePlain'); }, [state?.stats.totalPorts, locale]);
  useEffect(() => { const interval = window.setInterval(() => setNow(Date.now()), 5000); return () => window.clearInterval(interval); }, []);
  useEffect(() => {
    if (!state?.meta.ready || state.meta.lastError || !live || connection === 'offline') return;
    const active = new Set(state.ports.map(port => port.port));
    const next = new Map<number, boolean>();
    for (const port of watchlist) {
      const online = active.has(port); next.set(port, online);
      if (previousWatched.current.has(port) && previousWatched.current.get(port) !== online) {
        if (online) toast.success(t('watchlist.onlineBack', { port }), { description: state.ports.find(item => item.port === port)?.processName || undefined });
        else toast.warning(t('watchlist.stopped', { port }), { description: t('watchlist.stoppedMsg') });
      }
    }
    previousWatched.current = next;
  }, [state, watchlist, live, connection]);
  useEffect(() => {
    const keydown = (event: KeyboardEvent) => {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); setCommandOpen(value => !value); return; }
      if (event.ctrlKey || event.metaKey || event.altKey || event.defaultPrevented) return;
      const target = event.target as HTMLElement;
      if (target.closest('input,textarea,select,[contenteditable="true"],[role="combobox"],[role="dialog"]') || document.querySelector('[role="dialog"][data-state="open"]')) return;
      if (event.key === '/') { event.preventDefault(); focusSearch(); }
      else if (event.key.toLowerCase() === 'r') { event.preventDefault(); void scan(); }
      else if (event.key.toLowerCase() === 'v') setView(previous => previous === 'grid' ? 'table' : 'grid');
      else if (event.key === '?') { event.preventDefault(); setHelpOpen(true); }
    };
    window.addEventListener('keydown', keydown); return () => window.removeEventListener('keydown', keydown);
  }, [focusSearch, scan, setView]);

  const detailPort = detail ? state?.ports.find(port => port.port === detail.port) ?? detail : null;
  const status = !live ? t('header.paused') : connection === 'live' && !stale ? t('header.live') : connection === 'offline' ? t('header.disconnected') : connection === 'polling' ? l('POLLING', 'POLLING') : stale ? l('STALE', 'USANG') : t('header.connecting');
  const navGroup = (ids: Page[], label: string) => <SidebarGroup><SidebarGroupLabel className="text-[10px] tracking-wider uppercase">{label}</SidebarGroupLabel><SidebarGroupContent><SidebarMenu>{ids.map(id => { const item = routes.find(route => route.id === id)!; const Icon = item.icon; return <SidebarMenuItem key={id}><SidebarMenuButton asChild isActive={page === id} tooltip={routeTitle(item)} className="h-9"><a href={'#' + id} onClick={event => { event.preventDefault(); navigate(id); }}><Icon className="size-4" /><span>{routeTitle(item)}</span></a></SidebarMenuButton>{id === 'ports' && state && <SidebarMenuBadge className="font-mono text-[10px]">{state.stats.totalPorts}</SidebarMenuBadge>}{id === 'exposure' && !!state?.ports.some(port => port.wildcard) && <SidebarMenuBadge className="text-muted-foreground">{state.ports.filter(port => port.wildcard).length}</SidebarMenuBadge>}</SidebarMenuItem>; })}</SidebarMenu></SidebarGroupContent></SidebarGroup>;

  return <>
    <a href="#workspace-content" onClick={event => { event.preventDefault(); headingRef.current?.focus(); }} className="sr-only z-50 rounded-md bg-foreground px-4 py-2 text-background focus:not-sr-only focus:fixed focus:top-3 focus:left-3">{t('skip.link')}</a>
    <Sidebar variant="inset" collapsible="icon" className="border-r-0">
      <SidebarHeader className="gap-3 px-3 py-5"><SidebarMenu><SidebarMenuItem><SidebarMenuButton size="lg" asChild className="h-11 px-1.5 hover:bg-transparent"><a href="#overview" onClick={event => { event.preventDefault(); navigate('overview'); }}><div className="flex size-9 shrink-0 items-center justify-center rounded-xl border border-foreground/15 bg-foreground text-background"><Radar className="size-5" /></div><div className="grid flex-1 text-left"><span className="text-base font-semibold tracking-tight">PortScope<span className="ml-1 text-teal-600 dark:text-teal-400">.</span></span><span className="text-[10px] tracking-wider text-muted-foreground uppercase">{l('Local observability', 'Observabilitas lokal')}</span></div><Badge variant="outline" className="h-5 rounded px-1.5 text-[9px] text-muted-foreground">LOCAL</Badge></a></SidebarMenuButton></SidebarMenuItem></SidebarMenu><Button variant="outline" className="h-9 justify-start gap-2 bg-background/60 text-xs text-muted-foreground group-data-[collapsible=icon]:hidden" onClick={() => setCommandOpen(true)}><Search className="size-3.5" />{l('Quick navigation', 'Navigasi cepat')}<kbd className="ml-auto rounded border px-1 font-mono text-[10px]">⌘ K</kbd></Button></SidebarHeader>
      <SidebarContent className="gap-1">
        {navGroup(['overview', 'ports', 'connections', 'processes', 'exposure'], l('Workspace', 'Ruang kerja'))}
        {navGroup(['analytics', 'health', 'snapshots', 'activity'], l('Observe', 'Amati'))}
        {navGroup(['atlas', 'diagnostics', 'dns'], l('Networking', 'Jaringan'))}
        <SidebarGroup className="group-data-[collapsible=icon]:hidden"><SidebarGroupLabel className="justify-between text-[10px] tracking-wider uppercase"><span>{t('watchlist.title')}</span><span className="font-mono">{watchlist.length}/20</span></SidebarGroupLabel><SidebarGroupContent className="space-y-2 px-1"><div className="space-y-0.5">{watchlist.slice(0, 5).map(number => { const port = state?.ports.find(port => port.port === number); return <div key={number} className="group/watch flex items-center gap-2"><Button variant="ghost" size="sm" className="h-8 min-w-0 flex-1 justify-start gap-2 px-2 font-normal" disabled={!port} onClick={() => port && openPort(port)}><span className={cn('size-1.5 shrink-0 rounded-full', port ? 'bg-teal-600 dark:bg-teal-400' : 'bg-muted-foreground/40')} /><span className="font-mono text-xs">:{number}</span><span className="truncate text-[11px] text-muted-foreground">{port?.processName || t('watchlist.offline')}</span></Button><Button variant="ghost" size="icon" className="size-6 text-muted-foreground" aria-label={t('watchlist.removeAria', { port: number })} onClick={() => toggleWatch(number)}><X className="size-3" /></Button></div>; })}{!watchlist.length && <p className="px-2 py-1 text-xs leading-relaxed text-muted-foreground">{t('watchlist.emptyTitle')}</p>}{watchlist.length > 5 && <Button variant="link" size="sm" className="h-6 px-2 text-[11px]" onClick={() => navigate('settings')}>+{watchlist.length - 5} {l('more', 'lainnya')}</Button>}</div><form onSubmit={addWatch} className="flex gap-1.5"><Input value={watchInput} onChange={event => { setWatchInput(event.target.value); setWatchError(null); }} inputMode="numeric" maxLength={5} placeholder={t('watchlist.inputPlaceholder')} aria-label={t('watchlist.inputAria')} aria-invalid={!!watchError} aria-describedby={watchError ? 'watch-error' : undefined} className="h-8 min-w-0 bg-background/60 text-xs" /><Button type="submit" variant="outline" size="icon" className="size-8 shrink-0" aria-label={t('watchlist.add')}><Plus className="size-3.5" /></Button></form>{watchError && <p id="watch-error" role="alert" className="px-1 text-[11px] text-destructive">{t(watchError.key, watchError.params)}</p>}</SidebarGroupContent></SidebarGroup>
      </SidebarContent>
      <SidebarFooter className="gap-2 p-3"><SidebarMenu><SidebarMenuItem><SidebarMenuButton isActive={page === 'settings'} tooltip={l('Settings', 'Pengaturan')} onClick={() => navigate('settings')}><Settings2 className="size-4" /><span>{l('Settings', 'Pengaturan')}</span></SidebarMenuButton></SidebarMenuItem><SidebarMenuItem><SidebarMenuButton tooltip={t('header.help')} onClick={() => setHelpOpen(true)}><CircleHelp className="size-4" /><span>{t('help.title')}</span><kbd className="ml-auto text-[11px] text-muted-foreground">?</kbd></SidebarMenuButton></SidebarMenuItem></SidebarMenu><SidebarSeparator className="mx-0" /><div className="flex min-w-0 items-center gap-2.5 px-1 pt-1"><div className="flex size-8 shrink-0 items-center justify-center rounded-lg border bg-background"><Monitor className="size-4 text-muted-foreground" /></div><div className="min-w-0 group-data-[collapsible=icon]:hidden"><p className="truncate text-xs font-medium">{state?.meta.hostname || 'localhost'}</p><p className="text-[10px] text-muted-foreground">{l('Local workspace', 'Ruang kerja lokal')} · v{state?.meta.version || '1.0'}</p></div></div></SidebarFooter><SidebarRail />
    </Sidebar>
    <SidebarInset className={cn("min-w-0 overflow-x-clip border border-border/70 md:shadow-none", monitoringFocus && "h-dvh min-h-0 overflow-hidden md:h-[calc(100dvh-1rem)]")}>
      <header className="sticky top-0 z-30 flex h-16 shrink-0 items-center justify-between gap-3 border-b bg-background/95 px-4 backdrop-blur-sm md:rounded-t-xl lg:px-6">
        <div className="flex min-w-0 items-center gap-3"><SidebarTrigger className="-ml-1 shrink-0" aria-label={l('Toggle sidebar', 'Buka/tutup sidebar')} /><Separator orientation="vertical" className="mr-1 h-4" /><Breadcrumb className="min-w-0"><BreadcrumbList className="min-w-0 flex-nowrap text-xs"><BreadcrumbItem className="hidden sm:block"><BreadcrumbLink href="#overview" onClick={event => { event.preventDefault(); navigate('overview'); }}>{l('Workspace', 'Ruang kerja')}</BreadcrumbLink></BreadcrumbItem><BreadcrumbSeparator className="hidden sm:block" /><BreadcrumbItem className="min-w-0"><BreadcrumbPage className="truncate font-medium">{routeTitle(route)}</BreadcrumbPage></BreadcrumbItem></BreadcrumbList></Breadcrumb></div>
        <div className="flex shrink-0 items-center gap-1.5"><span className="mr-2 hidden font-mono text-[10px] text-muted-foreground xl:inline">{state?.meta.scannedAt ? l('Updated ', 'Diperbarui ') + formatAge(scanAge) + l(' ago', ' lalu') : t('header.scanNone')}</span><Badge variant="outline" className={cn('gap-1.5 rounded-md px-2 py-1 font-mono text-[9px] tracking-wider', live && connection === 'live' && !stale && 'border-teal-600/20 bg-teal-600/5 text-teal-700 dark:text-teal-400')}><span className={cn('size-1.5 rounded-full', live && connection === 'live' && !stale ? 'bg-teal-600 dark:bg-teal-400' : 'bg-muted-foreground')} />{status}</Badge><IconButton label={t(live ? 'header.pause' : 'header.resume')} onClick={() => setLive(!live)}>{live ? <Pause className="size-3.5" /> : <Play className="size-3.5" />}</IconButton><Separator orientation="vertical" className="mx-1 hidden h-4 sm:block" /><IconButton className="hidden size-8 sm:flex" label={l('Command palette', 'Palet perintah')} onClick={() => setCommandOpen(true)}><CommandIcon className="size-4" /></IconButton><DropdownMenu><DropdownMenuTrigger asChild><Button variant="ghost" size="icon" className="size-8" aria-label={t('language.toggleAria')}><Globe className="size-4" /></Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuLabel>{l('Language', 'Bahasa')}</DropdownMenuLabel><p className="max-w-64 px-2 pb-2 text-xs text-muted-foreground">{l('Core controls use the selected language. Advanced tools use English or Indonesian; Network atlas is currently English-only.', 'Kontrol inti memakai bahasa pilihan. Alat lanjutan memakai bahasa Inggris atau Indonesia; Atlas jaringan saat ini hanya dalam bahasa Inggris.')}</p><DropdownMenuRadioGroup value={locale} onValueChange={changeLanguage}>{LANGUAGES.map(language => <DropdownMenuRadioItem key={language.code} value={language.code}>{language.name}</DropdownMenuRadioItem>)}</DropdownMenuRadioGroup></DropdownMenuContent></DropdownMenu><IconButton className="size-8" label={t(resolvedTheme === 'dark' ? 'header.themeLight' : 'header.themeDark')} onClick={() => setTheme(resolvedTheme === 'dark' ? 'light' : 'dark')}>{resolvedTheme === 'dark' ? <Sun className="size-4" /> : <Moon className="size-4" />}</IconButton></div>
      </header>
      <div className={cn("mx-auto flex w-full max-w-[1680px] flex-1 flex-col gap-6 p-4 sm:p-6 lg:gap-7 lg:p-8", monitoringFocus && "min-h-0 gap-3 overflow-hidden p-3 sm:p-3 lg:gap-3 lg:p-4")}>
        <div className={cn("flex flex-wrap items-end justify-between gap-4", monitoringFocus && "sr-only")}><div><div className="mb-2 flex items-center gap-2 text-[10px] tracking-[0.14em] text-muted-foreground uppercase"><span className="size-1 rounded-full bg-teal-600 dark:bg-teal-400" />{l('Localhost /', 'Localhost /')} {state?.meta.hostname || l('This machine', 'Mesin ini')}</div><h1 ref={headingRef} tabIndex={-1} id="workspace-content" className="text-2xl font-semibold tracking-tight outline-none sm:text-[28px]">{routeTitle(route)}</h1><p className="mt-1.5 max-w-2xl text-sm leading-relaxed text-muted-foreground">{pageDescription(page)}</p></div><div className="flex items-center gap-2">{page === 'overview' && <Button variant="outline" size="sm" className="hidden sm:flex" onClick={() => navigate('snapshots')}><Copy className="size-3.5" />{l('Snapshots', 'Snapshot')}</Button>}<Button variant={page === 'overview' || page === 'ports' ? 'default' : 'outline'} size="sm" disabled={refreshing || (live && state?.meta.isScanning)} onClick={() => void scan()}><RefreshCw className={cn('size-3.5', (refreshing || (live && state?.meta.isScanning)) && 'animate-spin')} />{refreshing || (live && state?.meta.isScanning) ? t('page.scanning') : t('page.scan')}<kbd className="ml-2 hidden rounded border border-current/20 px-1 text-[9px] opacity-60 sm:inline">R</kbd></Button></div></div>
        {legacyServer && !monitoringFocus && <Alert className="bg-muted/20"><RefreshCw className="size-4" /><AlertTitle className="text-xs">{l('Restart the local server to enable new workspaces', 'Mulai ulang server lokal untuk mengaktifkan ruang kerja baru')}</AlertTitle><AlertDescription className="text-xs">{l('This browser has the new interface, but the running server predates continuous per-hop diagnostics. Existing ports remain available. Restart PortScope to enable independent hop monitoring and live hop charts.', 'Browser ini sudah memakai antarmuka baru, namun server belum mendukung diagnostik per-hop berkelanjutan. Data port tetap tersedia. Mulai ulang PortScope untuk mengaktifkan monitoring hop independen dan grafik hop live.')}</AlertDescription></Alert>}
        {!monitoringFocus && (!live || connection === 'offline' || connection === 'polling' || stale || error || state?.meta.lastError) && <Alert className={cn('flex flex-wrap items-center gap-3 bg-muted/30 [&>svg]:static [&>svg]:translate-y-0', connection === 'offline' && 'border-destructive/30')}><div className="text-muted-foreground">{!live ? <Pause className="size-4" /> : connection === 'offline' ? <WifiOff className="size-4" /> : <ShieldAlert className="size-4" />}</div><div className="min-w-0 flex-1"><AlertTitle className="mb-1 text-xs">{!live ? t('alerts.paused') : connection === 'offline' ? t('alerts.disconnected') : stale ? l('The last scan is stale.', 'Pemindaian terakhir sudah lama.') : connection === 'polling' ? t('alerts.disconnectedFallback') : l('Some observations are unavailable.', 'Sebagian pengamatan tidak tersedia.')}</AlertTitle><AlertDescription className="break-words text-xs">{error || state?.meta.lastError || (!live ? l('Your view is held. Manual scans still work.', 'Tampilan ditahan. Pemindaian manual tetap tersedia.') : l('Last known data stays visible while automatic recovery continues.', 'Data terakhir tetap terlihat saat pemulihan otomatis berlanjut.'))}</AlertDescription></div><Button variant="outline" size="sm" className="h-8 shrink-0 text-xs" disabled={refreshing} onClick={() => !live ? setLive(true) : void scan()}>{!live ? t('alerts.resume') : t('alerts.retry')}<ArrowRight className="size-3.5" /></Button></Alert>}
        <Updates settings={page === 'settings'} hidden={monitoringFocus} onSettings={openSettings} />
        <Suspense fallback={<LoadingWorkspace />}>
        {page === 'atlas' ? <Suspense fallback={<LoadingWorkspace />}><div lang="en"><Atlas network={network} live={live} onDiagnose={diagnose} /></div></Suspense> : page === 'diagnostics' ? <Diagnostics key={diagnosticTarget + ':' + diagnosticKind} network={network} live={live} initialTarget={diagnosticTarget} initialKind={diagnosticKind} onFocusChange={setDiagnosticFocus} /> : page === 'dns' ? <DnsTools live={live}><BrowserDns live={live} /></DnsTools> : page === 'settings' ? <SettingsPage state={state} theme={theme} setTheme={setTheme} locale={locale} changeLanguage={changeLanguage} live={live} setLive={setLive} compact={compact} setCompact={setCompact} pageSize={pageSize} setPageSize={setPageSize} favorites={favorites} watchlist={watchlist} onWatch={toggleWatch} onPortSelect={openPort} /> : !state || !state.meta.ready ? connection === 'offline' && !state ? <Card className="items-center py-16 text-center"><div className="flex size-12 items-center justify-center rounded-xl border bg-muted/50"><WifiOff className="size-5 text-muted-foreground" /></div><CardHeader className="gap-2"><CardTitle>{l('Waiting for your local monitor', 'Menunggu monitor lokal')}</CardTitle><CardDescription>{l('No snapshot is available yet. Keep PortScope running and try connecting again.', 'Snapshot belum tersedia. Pastikan PortScope berjalan dan coba hubungkan kembali.')}</CardDescription></CardHeader><Button variant="outline" onClick={() => void scan()} disabled={refreshing}><RefreshCw className={cn('size-4', refreshing && 'animate-spin')} />{t('common.retry')}</Button></Card> : <LoadingWorkspace /> : page === 'overview' || page === 'ports' ? <>{page === 'overview' && <Overview state={state} network={network} history={history} live={live && !stale && connection !== 'offline'} onNavigate={navigate} />}<PortBrowser state={state} favorites={favorites} watchlist={watchlist} onFavorite={toggleFavorite} onWatch={toggleWatch} onPortSelect={openPort} query={query} setQuery={setQuery} searchRef={searchRef} filter={filter} setFilter={setFilter} view={view === 'grid' ? 'grid' : 'table'} setView={setView} compact={compact} pageSize={[10, 15, 25, 50].includes(pageSize) ? pageSize : 15} setPageSize={setPageSize} overview={page === 'overview'} onScan={() => void scan()} /></> : page === 'health' ? <Health state={state} /> : page === 'snapshots' ? <Snapshots state={state} /> : <Insights page={page} state={state} network={network} history={history} onPortSelect={openPort} />}
        </Suspense>
        <footer className={cn("mt-auto flex flex-wrap items-center justify-between gap-2 border-t pt-4 text-[10px] text-muted-foreground", monitoringFocus && "hidden")}><span className="flex items-center gap-1.5"><Shield className="size-3" />{l('Monitoring is read-only. Stopping a listener requires explicit confirmation.', 'Pemantauan hanya membaca. Menghentikan listener memerlukan konfirmasi eksplisit.')}</span><span className="font-mono">{state ? state.meta.platform + ' / ' + state.meta.arch + ' · ' + formatMs(state.meta.scanDurationMs) + l(' scan', ' pindai') : 'localhost'}<span className="mx-2 text-border">/</span>PortScope</span></footer>
      </div>
    </SidebarInset>
    <PortDetail port={detailPort} open={detailOpen} onOpenChange={setDetailOpen} favorite={!!detailPort && favorites.includes(detailPort.port)} onFavorite={toggleFavorite} watched={!!detailPort && watchlist.includes(detailPort.port)} onWatch={toggleWatch} active={!!detailPort && !!state?.ports.some(port => port.port === detailPort.port)} platform={state?.meta.platform} onStopped={() => void scan()} onClosed={() => { if (opener.current?.isConnected && !opener.current.closest('[role="dialog"]')) opener.current.focus(); else headingRef.current?.focus(); }} />
    <CommandDialog open={commandOpen} onOpenChange={setCommandOpen} title={l('Command palette', 'Palet perintah')} description={l('Navigate workspaces, find a port, or run a command.', 'Buka ruang kerja, temukan port, atau jalankan perintah.')}><CommandInput placeholder={l('Search commands or listening ports…', 'Cari perintah atau port aktif…')} /><CommandList><CommandEmpty>{t('table.filteredTitle')}</CommandEmpty><CommandGroup heading={l('Workspaces', 'Ruang kerja')}>{routes.map(route => <CommandItem key={route.id} value={routeTitle(route) + ' ' + route.id} onSelect={() => { navigate(route.id); setCommandOpen(false); }}><route.icon className="size-4" /><span>{routeTitle(route)}</span>{page === route.id && <Check className="ml-auto size-3.5" />}</CommandItem>)}</CommandGroup>{!!state?.ports.length && <><CommandSeparator /><CommandGroup heading={t('page.title')}>{state.ports.map(port => <CommandItem key={port.port} value={port.port + ' ' + serviceName(port) + ' ' + port.processName} onSelect={() => { setCommandOpen(false); window.setTimeout(() => openPort(port), 0); }}><Radio className="size-4" /><span className="font-mono text-xs">:{port.port}</span><span className="truncate text-muted-foreground">{serviceName(port)}</span></CommandItem>)}</CommandGroup></>}<CommandSeparator /><CommandGroup heading={l('Actions', 'Tindakan')}><CommandItem onSelect={() => { void scan(); setCommandOpen(false); }}><RefreshCw />{t('page.scan')}<CommandShortcut>R</CommandShortcut></CommandItem><CommandItem onSelect={() => { setLive(!live); setCommandOpen(false); }}>{live ? <Pause /> : <Play />}{t(live ? 'header.pause' : 'header.resume')}</CommandItem><CommandItem onSelect={() => { setTheme(resolvedTheme === 'dark' ? 'light' : 'dark'); setCommandOpen(false); }}><Sun />{t('header.theme')}</CommandItem><CommandItem onSelect={() => { setCommandOpen(false); setHelpOpen(true); }}><CircleHelp />{t('help.title')}<CommandShortcut>?</CommandShortcut></CommandItem></CommandGroup></CommandList></CommandDialog>
    <Dialog open={helpOpen} onOpenChange={setHelpOpen}><DialogContent className="sm:max-w-md"><DialogHeader><DialogTitle>{t('help.title')}</DialogTitle><DialogDescription>{t('help.desc')}</DialogDescription></DialogHeader><div className="divide-y">{[['⌘ / Ctrl K', l('Open command palette', 'Buka palet perintah')], ['/', t('help.search')], ['R', t('help.rescan')], ['V', t('help.toggleView')], ['?', t('help.openHelp')], ['⌘ / Ctrl B', l('Toggle sidebar', 'Buka/tutup sidebar')], ['Esc', t('help.escape')]].map(([key, label]) => <div key={key} className="flex items-center justify-between gap-4 py-3 text-sm"><span className="text-muted-foreground">{label}</span><kbd className="shrink-0 rounded-md border bg-muted px-2 py-1 font-mono text-[10px]">{key}</kbd></div>)}</div><p className="text-xs leading-relaxed text-muted-foreground">{t('help.footnote')}</p></DialogContent></Dialog>
    <Toaster theme={resolvedTheme} position={isMobile ? 'bottom-center' : 'bottom-right'} closeButton />
  </>;
}

function pageDescription(page: Page) {
  switch (page) {
    case 'overview': return l('A clear view of what is listening on your machine, right now.', 'Pantau layanan yang sedang mendengarkan di mesin Anda.');
    case 'ports': return t('page.desc');
    case 'connections': return l('Inspect observed sockets, remote peers, and connection states.', 'Periksa soket, peer jarak jauh, dan status koneksi yang teramati.');
    case 'processes': return l('Trace local listeners and connections back to their owning processes.', 'Telusuri listener dan koneksi lokal ke proses pemiliknya.');
    case 'exposure': return l('Review bind addresses and potential network exposure. No active external scanning.', 'Tinjau alamat bind dan potensi eksposur jaringan. Tanpa pemindaian eksternal aktif.');
    case 'analytics': return l('Measured activity from this monitoring session. No synthetic data.', 'Aktivitas terukur dari sesi pemantauan ini. Tanpa data sintetis.');
    case 'health': return l('Run explicit, bounded checks against your loopback HTTP endpoints.', 'Jalankan pemeriksaan terbatas terhadap endpoint HTTP loopback Anda.');
    case 'snapshots': return l('Capture, compare, and export local listener inventories in this browser.', 'Simpan, bandingkan, dan ekspor inventaris listener lokal di browser ini.');
    case 'activity': return l('A session timeline of listeners arriving and leaving.', 'Linimasa sesi untuk listener yang muncul dan berhenti.');
    case 'atlas': return l('See where current sockets connect. Optional GeoIP, never invented locations.', 'Lihat tujuan koneksi soket saat ini. GeoIP opsional, tanpa lokasi rekaan.');
    case 'diagnostics': return l('Ping (ICMP), Traceroute / MTR (ICMP), TCP timing, and verified TLS inspection.', 'Ping (ICMP), Traceroute / MTR (ICMP), waktu TCP, dan inspeksi TLS terverifikasi.');
    case 'dns': return l('Inspect records and resolver behavior. Observe browser DNS through an optional external authority.', 'Periksa record dan perilaku resolver. Amati DNS browser lewat otoritas eksternal opsional.');
    case 'settings': return l('Make this workspace yours. Preferences stay in this browser.', 'Sesuaikan ruang kerja ini. Preferensi tersimpan di browser ini.');
  }
}

function Overview({ state, network, history, live, onNavigate }: { state: State; network: NetworkSnapshot | null; history: HistorySnapshot | null; live: boolean; onNavigate: (page: Page) => void }) {
  const exposed = state.ports.filter(port => port.wildcard).length;
  const cards = [
    { label: t('kpi.activePorts'), value: state.stats.totalPorts, icon: Radio, note: t('kpi.activeCtx', { count: state.stats.categoryCounts.system }), badge: l('Listening', 'Mendengarkan') },
    { label: t('kpi.webServices'), value: state.stats.webPorts, icon: Globe, note: t('kpi.webCtx', { http: state.stats.webPorts - state.stats.httpsPorts, https: state.stats.httpsPorts }), badge: 'HTTP / HTTPS' },
    { label: t('kpi.processes'), value: state.stats.processCount, icon: Cpu, note: t('kpi.procCtx'), badge: l('Unique PIDs', 'PID unik') },
    { label: l('Wildcard listeners', 'Listener wildcard'), value: exposed, icon: Shield, note: l('Potentially reachable beyond loopback', 'Berpotensi diakses di luar loopback'), badge: l('Review binds', 'Tinjau bind') },
  ];
  const samples = (history?.samples ?? []).filter(sample => Number.isFinite(Date.parse(sample.at)) && Number.isFinite(sample.totalPorts)).slice(-80);
  const chartData = samples.map(sample => ({ ...sample, timestamp: Date.parse(sample.at) }));
  return <>
    <section aria-label={t('page.summaryAria')} className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{cards.map(card => <Card key={card.label} className="gap-4 py-5 shadow-none"><CardHeader className="gap-0 px-5"><CardDescription className="text-xs font-medium">{card.label}</CardDescription><CardAction><card.icon className="size-4 text-muted-foreground" /></CardAction><CardTitle className="mt-3 font-mono text-[34px] leading-none font-semibold tracking-tight tabular-nums">{card.value.toLocaleString(getLocale())}</CardTitle></CardHeader><CardContent className="flex flex-wrap items-center justify-between gap-2 px-5"><p className="text-[11px] text-muted-foreground">{card.note}</p><Badge variant="outline" className="rounded-md px-1.5 py-0 text-[9px] font-normal text-muted-foreground">{card.badge}</Badge></CardContent></Card>)}</section>
    <div className="grid gap-4 xl:grid-cols-[minmax(0,2.2fr)_minmax(270px,1fr)]">
      <Card className="min-w-0 gap-4 shadow-none"><CardHeader className="gap-1.5"><CardTitle className="text-sm">{t('chart.title')}</CardTitle><CardDescription className="text-xs">{t('chart.desc')}</CardDescription><CardAction><Badge variant="outline" className="gap-1.5 rounded-md text-[9px] font-normal"><span className={cn('size-1.5 rounded-full', live ? 'bg-teal-600 dark:bg-teal-400' : 'bg-muted-foreground/50')} />{live ? t('chart.updating') : t('common.paused')}</Badge></CardAction></CardHeader><CardContent className="px-3 sm:px-5">{chartData.length ? <ChartContainer config={{ webPorts: { label: t('chart.legendWeb'), color: 'var(--chart-1)' }, tcpOnlyPorts: { label: 'TCP', color: 'var(--muted-foreground)' } }} className="h-[205px] w-full" aria-label={t('chart.title')}><LineChart accessibilityLayer data={chartData} margin={{ left: -16, right: 12, top: 6, bottom: 0 }}><CartesianGrid vertical={false} strokeDasharray="3 3" /><XAxis type="number" dataKey="timestamp" domain={['dataMin', 'dataMax']} tickFormatter={value => new Date(value).toLocaleTimeString(getLocale(), { hour: '2-digit', minute: '2-digit' })} tickLine={false} axisLine={false} minTickGap={45} tickMargin={10} /><YAxis allowDecimals={false} domain={[0, 'auto']} width={42} tickLine={false} axisLine={false} /><ChartTooltip content={<ChartTooltipContent labelFormatter={value => new Date(Number(value)).toLocaleTimeString(getLocale())} />} /><Line type="stepAfter" dataKey="webPorts" stroke="var(--color-webPorts)" strokeWidth={2} dot={chartData.length === 1} isAnimationActive={false} /><Line type="stepAfter" dataKey="tcpOnlyPorts" stroke="var(--color-tcpOnlyPorts)" strokeWidth={1.5} strokeDasharray="4 3" dot={chartData.length === 1} isAnimationActive={false} /></LineChart></ChartContainer> : <div className="flex h-[205px] flex-col items-center justify-center gap-3 rounded-lg border border-dashed bg-muted/15 text-center"><Activity className="size-6 text-muted-foreground/50" /><p className="text-xs text-muted-foreground">{history ? t('chart.collecting') : l('Session history is not available yet.', 'Riwayat sesi belum tersedia.')}</p>{!history && <p className="max-w-xs px-4 text-[11px] leading-relaxed text-muted-foreground">{l('An older server may need a restart. Current listener data is still shown below.', 'Server versi lama mungkin perlu dimulai ulang. Data listener terkini tetap ditampilkan di bawah.')}</p>}</div>}<div className="mt-4 flex flex-wrap items-center justify-between gap-3 px-1 text-[10px] text-muted-foreground"><div className="flex items-center gap-4"><span className="flex items-center gap-1.5"><span className="h-0.5 w-3 rounded-full bg-teal-600 dark:bg-teal-400" />{t('chart.legendWeb')}</span><span className="flex items-center gap-1.5"><span className="h-0.5 w-3 rounded-full bg-muted-foreground" />TCP</span></div><span>{samples.length} {l('measured samples · this session', 'sampel terukur · sesi ini')}</span></div></CardContent></Card>
      <Card className="gap-5 shadow-none"><CardHeader className="gap-1.5"><CardTitle className="text-sm">{l('Listener inventory', 'Inventaris listener')}</CardTitle><CardDescription className="text-xs">{l('What is running on this machine', 'Yang berjalan di mesin ini')}</CardDescription><CardAction><SquareTerminal className="size-4 text-muted-foreground" /></CardAction></CardHeader><CardContent className="space-y-4">{(['dev', 'app', 'system'] as const).map((category, index) => <div key={category} className="space-y-2"><div className="flex justify-between text-xs"><span className="text-muted-foreground">{t('category.' + category + 'Long')}</span><span className="font-mono font-medium">{state.stats.categoryCounts[category]}</span></div><Progress value={state.stats.totalPorts ? state.stats.categoryCounts[category] / state.stats.totalPorts * 100 : 0} aria-label={t('category.' + category + 'Long')} className={cn('h-1.5', index !== 0 && '[&>[data-slot=progress-indicator]]:bg-muted-foreground/50')} /></div>)}<Separator /><div className="flex items-center justify-between text-xs"><span className="text-muted-foreground">{l('Established connections', 'Koneksi established')}</span><span className="font-mono">{network?.ok ? network.summary.established : '—'}</span></div><Button variant="ghost" size="sm" className="h-8 w-full justify-between px-0 text-xs" onClick={() => onNavigate('connections')}>{l('Explore connections', 'Jelajahi koneksi')}<ArrowUpRight className="size-3.5" /></Button></CardContent></Card>
    </div>
  </>;
}

function PortBrowser({ state, favorites, watchlist, onFavorite, onWatch, onPortSelect, query, setQuery, searchRef, filter, setFilter, view, setView, compact, pageSize, setPageSize, overview, onScan }: {
  state: State; favorites: number[]; watchlist: number[]; onFavorite: (port: number) => void; onWatch: (port: number) => void; onPortSelect: (port: Port) => void;
  query: string; setQuery: (query: string) => void; searchRef: RefObject<HTMLInputElement | null>; filter: PortFilter; setFilter: (filter: PortFilter) => void;
  view: 'table' | 'grid'; setView: (value: 'table' | 'grid') => void; compact: boolean; pageSize: number; setPageSize: (size: number) => void; overview: boolean; onScan: () => void;
}) {
  const [protocol, setProtocol] = useState('all');
  const [exposure, setExposure] = useState('all');
  const [sort, setSort] = useState<Sort>('port');
  const [direction, setDirection] = useState<'asc' | 'desc'>('asc');
  const [page, setPage] = useState(1);
  const [selected, setSelected] = useState<number[]>([]);
  const [columns, setColumns] = useStorage<string[]>('portscope.columns', ['service', 'process', 'exposure', 'status', 'latency']);
  const favoriteSet = useMemo(() => new Set(favorites), [favorites]);
  const shown = (column: string) => columns.includes(column);
  const filtered = useMemo(() => {
    const terms = query.toLocaleLowerCase().trim().split(/\s+/).filter(Boolean);
    return state.ports.filter(port => {
      if (filter === 'web' && !['http', 'https'].includes(port.protocol)) return false;
      if (filter === 'dev' && port.category !== 'dev') return false;
      if (filter === 'system' && port.category !== 'system') return false;
      if (filter === 'favorites' && !favoriteSet.has(port.port)) return false;
      if (protocol !== 'all' && port.protocol !== protocol) return false;
      if (exposure !== 'all' && port.wildcard !== (exposure === 'wildcard')) return false;
      const haystack = [port.port, port.pid, port.title, port.processName, port.url, port.protocol, port.framework, port.category, ...port.bindAddresses].join(' ').toLocaleLowerCase();
      return terms.every(term => haystack.includes(term));
    }).sort((a, b) => {
      let result = 0;
      if (sort === 'port') result = a.port - b.port;
      else if (sort === 'service') result = serviceName(a).localeCompare(serviceName(b));
      else if (sort === 'process') result = (a.processName || '').localeCompare(b.processName || '');
      else if (sort === 'exposure') result = Number(a.wildcard) - Number(b.wildcard);
      else if (sort === 'seen') result = Date.parse(a.firstSeenAt) - Date.parse(b.firstSeenAt);
      else { if (a.responseTimeMs == null || b.responseTimeMs == null) return a.responseTimeMs == null ? b.responseTimeMs == null ? a.port - b.port : 1 : -1; result = a.responseTimeMs - b.responseTimeMs; }
      return (direction === 'asc' ? result : -result) || a.port - b.port;
    });
  }, [state.ports, filter, favoriteSet, query, protocol, exposure, sort, direction]);
  const pages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const current = Math.min(page, pages);
  const rows = filtered.slice((current - 1) * pageSize, current * pageSize);
  const selectedSet = new Set(selected);
  const selectedPorts = filtered.filter(port => selectedSet.has(port.port));
  const allOnPage = rows.length > 0 && rows.every(port => selectedSet.has(port.port));
  const someOnPage = rows.some(port => selectedSet.has(port.port));
  const hasFilters = query || filter !== 'all' || protocol !== 'all' || exposure !== 'all';
  useEffect(() => { setPage(1); setSelected([]); }, [query, filter, protocol, exposure, pageSize]);
  const toggleSelect = (port: number) => setSelected(previous => previous.includes(port) ? previous.filter(value => value !== port) : [...previous, port]);
  const selectPage = (checked: boolean) => setSelected(previous => checked ? [...new Set([...previous, ...rows.map(port => port.port)])] : previous.filter(value => !rows.some(port => port.port === value)));
  const reset = () => { setQuery(''); setFilter('all'); setProtocol('all'); setExposure('all'); };
  const sortColumn = (column: Sort) => { if (sort === column) setDirection(previous => previous === 'asc' ? 'desc' : 'asc'); else { setSort(column); setDirection('asc'); } };
  const sortLabel = (column: Sort, label: string) => <Button variant="ghost" size="sm" className="-ml-2 h-8 gap-1.5 px-2 text-[11px] font-medium text-muted-foreground hover:text-foreground" onClick={() => sortColumn(column)} aria-label={l('Sort by ', 'Urutkan menurut ') + label}>{label}{sort === column ? direction === 'asc' ? <ArrowUp className="size-3" /> : <ArrowDown className="size-3" /> : <ArrowDownUp className="size-3 opacity-40" />}</Button>;
  const rowActions = (port: Port) => <DropdownMenu><DropdownMenuTrigger asChild><Button variant="ghost" size="icon" className="size-7 text-muted-foreground" aria-label={l('Actions for port ', 'Tindakan port ') + port.port}><Ellipsis className="size-4" /></Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuLabel className="font-mono text-xs">localhost:{port.port}</DropdownMenuLabel><DropdownMenuSeparator /><DropdownMenuItem onSelect={() => onPortSelect(port)}><Radio />{t('table.portDetailsAria', { port: port.port })}</DropdownMenuItem><DropdownMenuItem onSelect={() => void copy(portUrl(port) || 'localhost:' + port.port)}><Copy />{l('Copy address', 'Salin alamat')}</DropdownMenuItem>{portUrl(port) && <DropdownMenuItem asChild><a href={portUrl(port)!} target="_blank" rel="noopener noreferrer"><ArrowUpRight />{t('action.open')}</a></DropdownMenuItem>}<DropdownMenuSeparator /><DropdownMenuItem onSelect={() => onFavorite(port.port)}><Star className={cn(favoriteSet.has(port.port) && 'fill-current')} />{favoriteSet.has(port.port) ? l('Remove favorite', 'Hapus favorit') : l('Add favorite', 'Tambahkan favorit')}</DropdownMenuItem><DropdownMenuItem onSelect={() => onWatch(port.port)}><Eye />{watchlist.includes(port.port) ? l('Remove from watchlist', 'Hapus dari pantauan') : l('Watch this port', 'Pantau port ini')}</DropdownMenuItem></DropdownMenuContent></DropdownMenu>;
  const statusBadge = (port: Port) => <Badge variant="outline" className={cn('gap-1.5 rounded-md px-1.5 py-0.5 font-mono text-[10px] font-normal', port.statusCode != null && port.statusCode < 400 && 'border-teal-600/15 bg-teal-600/5 text-teal-700 dark:text-teal-400')}><span className={cn('size-1 rounded-full', port.probeStatus === 'pending' ? 'bg-muted-foreground/50' : port.statusCode != null && port.statusCode < 400 ? 'bg-teal-600 dark:bg-teal-400' : 'bg-current')} />{port.probeStatus === 'pending' ? t('status.checking') : port.statusCode ?? t('activity.listening')}</Badge>;
  const tabs: [PortFilter, string, number][] = [['all', t('tabs.all'), state.ports.length], ['web', t('tabs.web'), state.stats.webPorts], ['dev', t('tabs.dev'), state.stats.categoryCounts.dev], ['system', t('tabs.system'), state.stats.categoryCounts.system], ['favorites', t('tabs.favorites'), state.ports.filter(port => favoriteSet.has(port.port)).length]];
  const visibleColumns: [string, string][] = [['service', t('table.headers.service')], ['process', t('table.headers.process')], ['exposure', l('Exposure', 'Eksposur')], ['status', t('table.headers.status')], ['latency', t('table.headers.latency')]];

  return <section className="min-w-0 space-y-4" aria-label={t('page.title')}>
    <div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2"><h2 className="text-base font-semibold tracking-tight">{overview ? l('Listening ports', 'Port yang mendengarkan') : l('Listener inventory', 'Inventaris listener')}</h2><Badge variant="secondary" className="rounded-md px-1.5 font-mono text-[10px] font-normal">{state.stats.totalPorts}</Badge></div><div className="flex items-center gap-2"><ToggleGroup type="single" variant="outline" size="sm" value={view} onValueChange={value => { if (value === 'table' || value === 'grid') setView(value); }} aria-label={t('page.viewAria')}><ToggleGroupItem value="table" className="h-8 px-2.5" aria-label={t('page.viewTable')}><Table2 className="size-3.5" /></ToggleGroupItem><ToggleGroupItem value="grid" className="h-8 px-2.5" aria-label={t('page.viewGrid')}><LayoutGrid className="size-3.5" /></ToggleGroupItem></ToggleGroup><DropdownMenu><DropdownMenuTrigger asChild><Button variant="outline" size="sm" className="h-8 text-xs" disabled={!filtered.length}><Download className="size-3.5" /><span className="hidden sm:inline">{l('Export', 'Ekspor')}</span><ChevronDown className="size-3" /></Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuLabel>{l('All filtered results', 'Semua hasil filter')} · {filtered.length}</DropdownMenuLabel><DropdownMenuItem onSelect={() => exportPorts(filtered, 'csv')}>{l('Download CSV', 'Unduh CSV')}</DropdownMenuItem><DropdownMenuItem onSelect={() => exportPorts(filtered, 'json')}>{l('Download JSON', 'Unduh JSON')}</DropdownMenuItem></DropdownMenuContent></DropdownMenu></div></div>
    <div className="flex flex-wrap items-center justify-between gap-3"><Tabs value={filter} onValueChange={value => setFilter(value as PortFilter)}><TabsList className="h-9 max-w-[calc(100vw-2rem)] overflow-x-auto bg-muted/65 p-1">{tabs.map(([key, label, count]) => <TabsTrigger key={key} value={key} className="h-7 gap-1.5 px-2.5 text-xs">{key === 'favorites' && <Star className="hidden size-3 sm:block" />}{label}<span className="hidden rounded px-1 font-mono text-[9px] text-muted-foreground sm:inline">{count}</span></TabsTrigger>)}</TabsList></Tabs><span className="hidden text-[11px] text-muted-foreground lg:inline">{t('table.desc')}</span></div>
    <div className="flex flex-wrap items-center gap-2"><div className="relative min-w-[180px] flex-1 lg:max-w-sm"><Search className="pointer-events-none absolute top-2.5 left-3 size-3.5 text-muted-foreground" /><Input ref={searchRef} value={query} onChange={event => setQuery(event.target.value)} onKeyDown={event => { if (event.key === 'Escape') { setQuery(''); event.currentTarget.blur(); } }} aria-label={t('page.searchAria')} placeholder={t('page.searchPlaceholder')} className="h-9 pr-9 pl-9 text-xs" />{query ? <Button variant="ghost" size="icon" className="absolute top-0.5 right-0.5 size-8" aria-label={l('Clear search', 'Hapus pencarian')} onClick={() => { setQuery(''); searchRef.current?.focus(); }}><X className="size-3.5" /></Button> : <kbd className="pointer-events-none absolute top-2.5 right-3 rounded border px-1 font-mono text-[9px] leading-3 text-muted-foreground">/</kbd>}</div><Select value={protocol} onValueChange={setProtocol}><SelectTrigger className="h-9 w-[120px] text-xs" aria-label={l('Filter protocol', 'Filter protokol')}><SelectValue placeholder={l('Protocol', 'Protokol')} /></SelectTrigger><SelectContent><SelectItem value="all">{l('All protocols', 'Semua protokol')}</SelectItem><SelectItem value="http">HTTP</SelectItem><SelectItem value="https">HTTPS</SelectItem><SelectItem value="tcp">TCP</SelectItem></SelectContent></Select><Select value={exposure} onValueChange={setExposure}><SelectTrigger className="h-9 w-[135px] text-xs" aria-label={l('Filter exposure', 'Filter eksposur')}><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">{l('All exposure', 'Semua eksposur')}</SelectItem><SelectItem value="loopback">{l('Loopback only', 'Hanya loopback')}</SelectItem><SelectItem value="wildcard">{l('Wildcard bind', 'Bind wildcard')}</SelectItem></SelectContent></Select><DropdownMenu><DropdownMenuTrigger asChild><Button variant="outline" size="sm" className="h-9 gap-1.5 text-xs"><ArrowDownUp className="size-3.5" /><span className="hidden sm:inline">{l('Sort', 'Urutkan')}</span></Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuLabel>{t('table.sortAria')}</DropdownMenuLabel><DropdownMenuRadioGroup value={sort} onValueChange={value => setSort(value as Sort)}>{(['port', 'service', 'process', 'latency', 'exposure', 'seen'] as const).map(key => <DropdownMenuRadioItem key={key} value={key}>{({ port: t('table.headers.port'), service: t('table.headers.service'), process: t('table.headers.process'), latency: t('table.headers.latency'), exposure: l('Exposure', 'Eksposur'), seen: l('First observed', 'Pertama diamati') })[key]}</DropdownMenuRadioItem>)}</DropdownMenuRadioGroup><DropdownMenuSeparator /><DropdownMenuRadioGroup value={direction} onValueChange={value => setDirection(value as 'asc' | 'desc')}><DropdownMenuRadioItem value="asc">{l('Ascending', 'Menaik')}</DropdownMenuRadioItem><DropdownMenuRadioItem value="desc">{l('Descending', 'Menurun')}</DropdownMenuRadioItem></DropdownMenuRadioGroup></DropdownMenuContent></DropdownMenu>{view === 'table' && <DropdownMenu><DropdownMenuTrigger asChild><Button variant="outline" size="sm" className="ml-auto h-9 gap-1.5 text-xs"><ListFilter className="size-3.5" /><span className="hidden xl:inline">{l('Columns', 'Kolom')}</span></Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuLabel>{l('Visible columns', 'Kolom terlihat')}</DropdownMenuLabel>{visibleColumns.map(([key, label]) => <DropdownMenuCheckboxItem key={key} checked={shown(key)} onSelect={event => event.preventDefault()} onCheckedChange={checked => setColumns(previous => checked ? [...previous, key] : previous.filter(value => value !== key))}>{label}</DropdownMenuCheckboxItem>)}</DropdownMenuContent></DropdownMenu>}{hasFilters && <Button variant="ghost" size="sm" className="h-9 px-2 text-xs text-muted-foreground" onClick={reset}><X className="size-3.5" />{l('Reset', 'Reset')}</Button>}</div>
    {selectedPorts.length > 0 && <div className="flex flex-wrap items-center gap-2 rounded-lg border bg-muted/40 px-3 py-2"><span className="mr-1 text-xs font-medium">{selectedPorts.length} {l('selected', 'dipilih')}</span><Button variant="outline" size="sm" className="h-7 text-[11px]" onClick={() => void copy(selectedPorts.map(port => portUrl(port) || 'localhost:' + port.port).join('\n'))}><Copy className="size-3" />{l('Copy addresses', 'Salin alamat')}</Button><DropdownMenu><DropdownMenuTrigger asChild><Button variant="outline" size="sm" className="h-7 text-[11px]"><Download className="size-3" />{l('Export selected', 'Ekspor pilihan')}<ChevronDown className="size-3" /></Button></DropdownMenuTrigger><DropdownMenuContent><DropdownMenuItem onSelect={() => exportPorts(selectedPorts, 'csv')}>CSV</DropdownMenuItem><DropdownMenuItem onSelect={() => exportPorts(selectedPorts, 'json')}>JSON</DropdownMenuItem></DropdownMenuContent></DropdownMenu>{selectedPorts.length !== filtered.length && <Button variant="ghost" size="sm" className="h-7 text-[11px]" onClick={() => setSelected(filtered.map(port => port.port))}>{l('Select all ', 'Pilih semua ') + filtered.length}</Button>}<Button variant="ghost" size="icon" className="ml-auto size-7" aria-label={l('Clear selection', 'Hapus pilihan')} onClick={() => setSelected([])}><X className="size-3.5" /></Button></div>}
    {!filtered.length ? <Card className="items-center gap-4 border-dashed py-14 text-center shadow-none"><div className="flex size-11 items-center justify-center rounded-xl border bg-muted/40"><Search className="size-5 text-muted-foreground" /></div><div className="space-y-2 px-6"><h3 className="text-sm font-semibold">{t(hasFilters ? 'table.filteredTitle' : 'table.emptyTitle')}</h3><p className="max-w-md text-xs leading-relaxed text-muted-foreground">{t(hasFilters ? 'table.filteredDesc' : 'table.emptyDesc')}</p></div><Button variant="outline" size="sm" onClick={hasFilters ? reset : onScan}>{t(hasFilters ? 'common.resetFilters' : 'table.emptyScan')}</Button></Card> : view === 'table' ? <div className="overflow-hidden rounded-lg border"><Table><TableHeader className="bg-muted/30"><TableRow className="hover:bg-transparent"><TableHead className="w-10 pl-4"><Checkbox checked={allOnPage ? true : someOnPage ? 'indeterminate' : false} onCheckedChange={checked => selectPage(checked === true)} aria-label={l('Select current page', 'Pilih halaman ini')} /></TableHead><TableHead className="w-7 px-1"><Star className="size-3 text-muted-foreground" /><span className="sr-only">{t('tabs.favorites')}</span></TableHead><TableHead aria-sort={sort === 'port' ? direction === 'asc' ? 'ascending' : 'descending' : 'none'}>{sortLabel('port', t('table.headers.port'))}</TableHead>{shown('service') && <TableHead aria-sort={sort === 'service' ? direction === 'asc' ? 'ascending' : 'descending' : 'none'}>{sortLabel('service', t('table.headers.service'))}</TableHead>}{shown('process') && <TableHead aria-sort={sort === 'process' ? direction === 'asc' ? 'ascending' : 'descending' : 'none'}>{sortLabel('process', t('table.headers.process'))}</TableHead>}{shown('exposure') && <TableHead aria-sort={sort === 'exposure' ? direction === 'asc' ? 'ascending' : 'descending' : 'none'}>{sortLabel('exposure', l('Exposure', 'Eksposur'))}</TableHead>}{shown('status') && <TableHead className="text-[11px]">{t('table.headers.status')}</TableHead>}{shown('latency') && <TableHead className="text-right" aria-sort={sort === 'latency' ? direction === 'asc' ? 'ascending' : 'descending' : 'none'}>{sortLabel('latency', t('table.headers.latency'))}</TableHead>}<TableHead className="w-16 pr-4"><span className="sr-only">{t('table.headers.actions')}</span></TableHead></TableRow></TableHeader><TableBody>{rows.map(port => <TableRow key={port.port} data-state={selectedSet.has(port.port) ? 'selected' : undefined} className="group/row cursor-pointer" onClick={event => { if (event.currentTarget.contains(event.target as Node) && !(event.target as HTMLElement).closest('button,a,input,[role="checkbox"]')) onPortSelect(port); }}><TableCell className={cn('pl-4', compact ? 'py-2' : 'py-3')}><Checkbox checked={selectedSet.has(port.port)} onCheckedChange={() => toggleSelect(port.port)} aria-label={l('Select port ', 'Pilih port ') + port.port} /></TableCell><TableCell className="px-1"><Button variant="ghost" size="icon" className={cn('size-7 text-muted-foreground/45 hover:text-foreground', favoriteSet.has(port.port) && 'text-foreground')} aria-pressed={favoriteSet.has(port.port)} aria-label={t(favoriteSet.has(port.port) ? 'fav.remove' : 'fav.add', { port: port.port })} onClick={() => onFavorite(port.port)}><Star className={cn('size-3.5', favoriteSet.has(port.port) && 'fill-current')} /></Button></TableCell><TableCell className="whitespace-nowrap"><Button variant="link" className="h-auto p-0 font-mono text-[13px] font-semibold text-foreground" onClick={() => onPortSelect(port)} aria-label={t('table.portDetailsAria', { port: port.port })}>:{port.port}</Button><span className="mt-0.5 block font-mono text-[9px] text-muted-foreground uppercase">{port.protocol === 'pending' ? 'TCP' : port.protocol}</span></TableCell>{shown('service') && <TableCell className="min-w-36"><p className="max-w-[270px] truncate text-xs font-medium">{serviceName(port)}</p><p className="mt-1 flex items-center gap-1.5 text-[10px] text-muted-foreground">{port.framework || t('category.' + port.category + 'Long')}{port.isSelf && <span className="rounded border px-1 text-[8px]">{t('dialog.selfBadge')}</span>}{watchlist.includes(port.port) && <Eye className="size-3" />}</p></TableCell>}{shown('process') && <TableCell><p className="max-w-40 truncate font-mono text-[11px]">{port.processName || '—'}</p><p className="mt-1 font-mono text-[10px] text-muted-foreground">PID {port.pid}</p></TableCell>}{shown('exposure') && <TableCell><span className="flex items-center gap-1.5 text-[11px] text-muted-foreground">{port.wildcard ? <ShieldAlert className="size-3" /> : <Shield className="size-3" />}{port.wildcard ? l('Wildcard', 'Wildcard') : 'Loopback'}</span><p className="mt-1 max-w-40 truncate font-mono text-[9px] text-muted-foreground/70">{port.bindAddresses.join(', ')}</p></TableCell>}{shown('status') && <TableCell>{statusBadge(port)}</TableCell>}{shown('latency') && <TableCell className="text-right font-mono text-[11px] tabular-nums text-muted-foreground">{formatMs(port.responseTimeMs)}</TableCell>}<TableCell className="pr-3"><div className="flex items-center justify-end gap-1">{portUrl(port) && <Button variant="ghost" size="icon" className="size-7 text-muted-foreground" asChild><a href={portUrl(port)!} target="_blank" rel="noopener noreferrer" aria-label={t('action.openAria', { port: port.port })}><ArrowUpRight className="size-3.5" /></a></Button>}{rowActions(port)}</div></TableCell></TableRow>)}</TableBody></Table></div> : <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4">{rows.map(port => <Card key={port.port} className={cn('gap-4 py-4 shadow-none transition-colors hover:border-foreground/25', selectedSet.has(port.port) && 'bg-muted/50')}><CardHeader className="gap-3 px-4"><div className="flex items-center justify-between gap-2"><Checkbox checked={selectedSet.has(port.port)} onCheckedChange={() => toggleSelect(port.port)} aria-label={l('Select port ', 'Pilih port ') + port.port} /><div className="ml-auto flex gap-1"><Button variant="ghost" size="icon" className="size-6 text-muted-foreground" aria-pressed={favoriteSet.has(port.port)} aria-label={t(favoriteSet.has(port.port) ? 'fav.remove' : 'fav.add', { port: port.port })} onClick={() => onFavorite(port.port)}><Star className={cn('size-3.5', favoriteSet.has(port.port) && 'fill-current text-foreground')} /></Button>{rowActions(port)}</div></div><div className="flex items-center gap-2"><Button variant="link" className="h-auto p-0 font-mono text-xl font-semibold text-foreground" onClick={() => onPortSelect(port)} aria-label={t('table.portDetailsAria', { port: port.port })}>:{port.port}</Button><Badge variant="secondary" className="rounded px-1.5 text-[9px] uppercase">{port.protocol}</Badge></div><CardTitle className="truncate text-sm leading-normal">{serviceName(port)}</CardTitle><CardDescription className="truncate font-mono text-[10px]">{port.processName || '—'} · PID {port.pid}</CardDescription></CardHeader><CardContent className="space-y-3 px-4"><div className="flex items-center justify-between gap-2">{statusBadge(port)}<span className="font-mono text-[10px] text-muted-foreground">{formatMs(port.responseTimeMs)}</span></div><Separator /><div className="flex items-center justify-between text-[10px] text-muted-foreground"><span className="flex items-center gap-1"><Shield className="size-3" />{port.wildcard ? l('Wildcard bind', 'Bind wildcard') : 'Loopback'}</span><Button variant="ghost" size="sm" className="h-6 px-0 text-[10px]" onClick={() => onPortSelect(port)}>{l('Details', 'Detail')}<ArrowRight className="size-3" /></Button></div></CardContent></Card>)}</div>}
    <div className="flex flex-wrap items-center justify-between gap-3 text-[11px] text-muted-foreground"><span>{filtered.length ? (current - 1) * pageSize + 1 : 0}–{Math.min(current * pageSize, filtered.length)} {l('of', 'dari')} <span className="font-medium text-foreground">{filtered.length}</span> {l('ports', 'port')}{hasFilters && <span> · {state.ports.length} {l('total', 'total')}</span>}</span><div className="flex items-center gap-3"><Select value={String(pageSize)} onValueChange={value => setPageSize(Number(value))}><SelectTrigger className="h-8 w-[100px] text-[11px]" aria-label={l('Rows per page', 'Baris per halaman')}><SelectValue /></SelectTrigger><SelectContent>{[10, 15, 25, 50].map(size => <SelectItem key={size} value={String(size)}>{size} / {l('page', 'halaman')}</SelectItem>)}</SelectContent></Select><Pagination className="w-auto"><PaginationContent><PaginationItem><Button variant="outline" size="icon" className="size-8" disabled={current === 1} onClick={() => setPage(current - 1)} aria-label={l('Previous page', 'Halaman sebelumnya')}><ChevronLeft className="size-3.5" /></Button></PaginationItem><PaginationItem><span className="px-2 font-mono text-[10px]">{current} / {pages}</span></PaginationItem><PaginationItem><Button variant="outline" size="icon" className="size-8" disabled={current === pages} onClick={() => setPage(current + 1)} aria-label={l('Next page', 'Halaman berikutnya')}><ChevronRight className="size-3.5" /></Button></PaginationItem></PaginationContent></Pagination></div></div>
  </section>;
}

function SettingsPage({ state, theme, setTheme, locale, changeLanguage, live, setLive, compact, setCompact, pageSize, setPageSize, favorites, watchlist, onWatch, onPortSelect }: {
  state: State | null; theme: Theme; setTheme: (theme: Theme) => void; locale: string; changeLanguage: (locale: string) => void;
  live: boolean; setLive: (live: boolean) => void; compact: boolean; setCompact: (compact: boolean) => void; pageSize: number; setPageSize: (size: number) => void;
  favorites: number[]; watchlist: number[]; onWatch: (port: number) => void; onPortSelect: (port: Port) => void;
}) {
  return <div className="grid items-start gap-5 xl:grid-cols-[minmax(0,1.5fr)_minmax(280px,1fr)]"><div className="space-y-5"><Card className="shadow-none"><CardHeader><CardTitle className="text-sm">{l('Appearance', 'Tampilan')}</CardTitle><CardDescription className="text-xs">{l('A quiet workspace, in your preferred light.', 'Ruang kerja tenang, dengan tampilan pilihan Anda.')}</CardDescription></CardHeader><CardContent className="space-y-6"><RadioGroup value={['light', 'dark', 'system'].includes(theme) ? theme : 'dark'} onValueChange={value => setTheme(value as Theme)} className="grid grid-cols-3 gap-3" aria-label={l('Color theme', 'Tema warna')}>{([{ value: 'light', label: l('Light', 'Terang'), icon: Sun }, { value: 'dark', label: l('Dark', 'Gelap'), icon: Moon }, { value: 'system', label: l('System', 'Sistem'), icon: Monitor }]).map(item => <Label key={item.value} htmlFor={'theme-' + item.value} className={cn('flex cursor-pointer flex-col items-center gap-3 rounded-lg border p-4 text-xs transition-colors hover:bg-muted/40', theme === item.value && 'border-foreground bg-muted/40')}><item.icon className="size-5 text-muted-foreground" /><span className="flex items-center gap-2"><RadioGroupItem value={item.value} id={'theme-' + item.value} className="size-3.5" />{item.label}</span></Label>)}</RadioGroup><Separator /><div className="flex items-center justify-between gap-6"><div className="space-y-1"><Label htmlFor="compact-mode" className="text-xs">{l('Compact tables', 'Tabel ringkas')}</Label><p className="text-xs text-muted-foreground">{l('Fit more listener rows into your viewport.', 'Tampilkan lebih banyak baris listener di layar.')}</p></div><Switch id="compact-mode" checked={compact} onCheckedChange={setCompact} /></div><div className="flex items-center justify-between gap-6"><Label htmlFor="default-page-size" className="text-xs">{l('Default rows per page', 'Jumlah baris per halaman')}</Label><Select value={String([10, 15, 25, 50].includes(pageSize) ? pageSize : 15)} onValueChange={value => setPageSize(Number(value))}><SelectTrigger id="default-page-size" className="h-8 w-24 text-xs"><SelectValue /></SelectTrigger><SelectContent>{[10, 15, 25, 50].map(size => <SelectItem key={size} value={String(size)}>{size}</SelectItem>)}</SelectContent></Select></div></CardContent></Card><Card className="shadow-none"><CardHeader><CardTitle className="text-sm">{l('Language & monitoring', 'Bahasa & pemantauan')}</CardTitle><CardDescription className="text-xs">{l('Pause holds observations and cancels active diagnostics in this view.', 'Jeda menahan pengamatan dan membatalkan diagnostik aktif di tampilan ini.')}</CardDescription></CardHeader><CardContent className="space-y-5"><div className="flex flex-wrap items-center justify-between gap-4"><Label htmlFor="workspace-language" className="text-xs">{l('Interface language', 'Bahasa antarmuka')}</Label><Select value={locale} onValueChange={changeLanguage}><SelectTrigger id="workspace-language" className="h-9 w-48 text-xs"><SelectValue /></SelectTrigger><SelectContent>{LANGUAGES.map(language => <SelectItem key={language.code} value={language.code}>{language.name}</SelectItem>)}</SelectContent></Select></div><p className="rounded-md border bg-muted/20 p-3 text-[11px] leading-relaxed text-muted-foreground">{l('Core controls use the selected language. Advanced tools use English or Indonesian; Network atlas is currently English-only.', 'Kontrol inti memakai bahasa pilihan. Alat lanjutan memakai bahasa Inggris atau Indonesia; Atlas jaringan saat ini hanya dalam bahasa Inggris.')}</p><Separator /><div className="flex items-center justify-between gap-6"><div className="space-y-1"><Label htmlFor="live-updates" className="text-xs">{l('Live updates', 'Pembaruan langsung')}</Label><p className="text-xs text-muted-foreground">{l('Pause incoming data without stopping the monitor.', 'Jeda data masuk tanpa menghentikan monitor.')}</p></div><Switch id="live-updates" checked={live} onCheckedChange={setLive} /></div><p className="text-[11px] leading-relaxed text-muted-foreground">{l('Automatic scans are controlled by the local server. Manual scans remain available when live updates are paused.', 'Pemindaian otomatis dikendalikan server lokal. Pemindaian manual tetap tersedia saat pembaruan langsung dijeda.')}</p></CardContent></Card></div><div className="space-y-5"><Card className="gap-4 shadow-none"><CardHeader><CardTitle className="text-sm">{t('watchlist.title')}</CardTitle><CardDescription className="text-xs">{l('Toast alerts when watched ports appear or leave while this tab is open.', 'Notifikasi saat port pantauan muncul atau berhenti selama tab ini terbuka.')}</CardDescription><CardAction><Badge variant="outline" className="font-mono text-[10px]">{watchlist.length}/20</Badge></CardAction></CardHeader><CardContent>{watchlist.length ? <div className="divide-y">{watchlist.map(number => { const port = state?.ports.find(port => port.port === number); return <div key={number} className="flex items-center gap-2 py-2"><span className={cn('size-1.5 rounded-full', port ? 'bg-teal-600 dark:bg-teal-400' : 'bg-muted-foreground/40')} /><Button variant="link" className="h-auto p-0 font-mono text-xs text-foreground" disabled={!port} onClick={() => port && onPortSelect(port)}>:{number}</Button><span className="min-w-0 flex-1 truncate text-[11px] text-muted-foreground">{port?.processName || t('watchlist.offline')}</span><Button variant="ghost" size="icon" className="size-7" aria-label={t('watchlist.removeAria', { port: number })} onClick={() => onWatch(number)}><X className="size-3.5" /></Button></div>; })}</div> : <p className="py-4 text-xs leading-relaxed text-muted-foreground">{t('watchlist.emptyDesc')}</p>}<p className="mt-3 text-[10px] text-muted-foreground">{l('Add a port from its details, row menu, or the sidebar.', 'Tambahkan port dari detail, menu baris, atau sidebar.')}</p></CardContent></Card><Card className="gap-4 shadow-none"><CardHeader><CardTitle className="text-sm">{l('Local monitor', 'Monitor lokal')}</CardTitle><CardDescription className="text-xs">{l('No cloud account or automatic remote telemetry. Explicit tools may contact selected targets or disclosed providers.', 'Tanpa akun cloud atau telemetri otomatis. Alat yang dijalankan dapat menghubungi target atau penyedia yang disebutkan.')}</CardDescription><CardAction><Monitor className="size-4 text-muted-foreground" /></CardAction></CardHeader><CardContent className="space-y-3">{[[l('Hostname', 'Nama host'), state?.meta.hostname || '—'], [l('Platform', 'Platform'), state ? state.meta.platform + ' / ' + state.meta.arch : '—'], [l('Server', 'Server'), state ? 'localhost:' + state.meta.serverPort : '—'], [l('Version', 'Versi'), state?.meta.version || '—'], [l('Scan interval', 'Interval pindai'), state ? formatMs(state.meta.scanIntervalMs) : '—'], [l('Favorites', 'Favorit'), String(favorites.length)]].map(([label, value]) => <div key={label} className="flex justify-between gap-4 text-[11px]"><span className="text-muted-foreground">{label}</span><span className="truncate font-mono">{value}</span></div>)}<Separator /><p className="flex gap-2 text-[11px] leading-relaxed text-muted-foreground"><Shield className="mt-0.5 size-3.5 shrink-0" />{t('help.footnote')}</p></CardContent></Card></div></div>;
}

export default function App() {
  return <TooltipProvider delayDuration={250}><SidebarProvider><Workbench /></SidebarProvider></TooltipProvider>;
}
